# Let me look for symmetries or patterns in the top section
top_section = [
    [1, 1, 1, 2],
    [1, 1, 2, 1],  
    [1, 2, 2, 2]
]

# Check if it's a rotation of something
import copy

def rotate90(grid):
    return [list(reversed([row[j] for row in grid])) for j in range(len(grid[0]))]

def rotate180(grid):
    return [list(reversed(row[::-1])) for row in reversed(grid)]

def rotate270(grid):
    return [list(reversed([row[-j-1] for row in grid])) for j in range(len(grid[0]))]

print("Original:")
for row in top_section: print(row)
print("\nRotate 90°:")
for row in rotate90(top_section): print(row)
print("\nRotate 180°:")
for row in rotate180(top_section): print(row)
print("\nRotate 270°:")
for row in rotate270(top_section): print(row)

# Maybe it relates to position indices?
